int bit_get(bitword_t* bitstorage, counter_t index) {
    return (bitstorage[wordindex(index)] >> bitindex_calc(index)) & 1;
}

void bit_set(bitword_t* bitstorage, counter_t index) {
    bitstorage[wordindex(index)] |= markmask_calc(index);
}

void bit_clear(bitword_t* bitstorage, counter_t index) {
    bitstorage[wordindex(index)] &= ~markmask_calc(index);
}

// Helper functions for testing
void print_bits(bitword_t* bitstorage, counter_t start, counter_t end) {
    for (counter_t i = start; i <= end; i++) {
        printf("%d", bit_get(bitstorage, i) ? 1 : 0);
        if ((i+1) % 8 == 0) printf(" ");
    }
    printf("\n");
}

void set_pattern(bitword_t* bitstorage, counter_t start, counter_t size, const char* pattern) {
    for (counter_t i = 0; i < size; i++) {
        if (pattern[i % strlen(pattern)] == '1') {
            bit_set(bitstorage, start + i);
        } else {
            bit_clear(bitstorage, start + i);
        }
    }
}

bool verify_pattern(bitword_t* bitstorage, counter_t start, counter_t end, const char* pattern) {
    size_t pattern_len = strlen(pattern);
    for (counter_t i = start; i < end; i++) {
        bool expected = pattern[(i - start) % pattern_len] == '1';
        bool actual = bit_get(bitstorage, i);
        if (expected != actual) {
            printf("Pattern mismatch at bit %ju: expected %d, got %d\n", 
                   (uintmax_t)i, expected, actual);
            return false;
        }
    }
    return true;
}

