// Test for continuePattern_aligned
void test_continuePattern_aligned() {
    printf("Testing continuePattern_aligned...\n");
    
    const counter_t bitstorage_size = 512;
    const counter_t word_size = WORD_SIZE_BITS;
    bitword_t* bitstorage = (bitword_t*)calloc(wordindex(bitstorage_size) + 1, sizeof(bitword_t));
    
    // Create a pattern that's exactly one word long and aligned
    const counter_t pattern_start = word_size; // Start at a word boundary
    const counter_t pattern_size = word_size;  // One word size
    
    // Create a complex pattern
    for (counter_t i = 0; i < pattern_size; i++) {
        if (i % 3 == 0 || i % 5 == 0) {
            bit_set(bitstorage, pattern_start + i);
        }
    }
    
    // Extend the pattern
    continuePattern_aligned(bitstorage, pattern_start, pattern_size, pattern_start + pattern_size * 5);
    
    // Verify each copy of the pattern
    for (counter_t i = 1; i <= 4; i++) {
        for (counter_t j = 0; j < pattern_size; j++) {
            bool expected = bit_get(bitstorage, pattern_start + j);
            bool actual = bit_get(bitstorage, pattern_start + pattern_size * i + j);
            assert(expected == actual);
        }
    }
    
    printf("  ✓ Word-aligned pattern test passed\n");
    
    // Test with multi-word pattern
    memset(bitstorage, 0, (wordindex(bitstorage_size) + 1) * sizeof(bitword_t));
    
    const counter_t multi_pattern_start = word_size * 2;
    const counter_t multi_pattern_size = word_size * 3;
    
    // Create a pattern
    for (counter_t i = 0; i < multi_pattern_size; i++) {
        if ((i / 8) % 2 == 0) {
            bit_set(bitstorage, multi_pattern_start + i);
        }
    }
    
    // Extend the pattern
    continuePattern_aligned(bitstorage, multi_pattern_start, multi_pattern_size, 
                          multi_pattern_start + multi_pattern_size * 3);
    
    // Verify
    for (counter_t i = 1; i <= 2; i++) {
        for (counter_t j = 0; j < multi_pattern_size; j++) {
            bool expected = bit_get(bitstorage, multi_pattern_start + j);
            bool actual = bit_get(bitstorage, multi_pattern_start + multi_pattern_size * i + j);
            assert(expected == actual);
        }
    }
    
    printf("  ✓ Multi-word aligned pattern test passed\n");
    
    free(bitstorage);
}

// Test for continuePattern_shiftright
void test_continuePattern_shiftright() {
    printf("Testing continuePattern_shiftright...\n");
    
    const counter_t bitstorage_size = 512;
    bitword_t* bitstorage = (bitword_t*)calloc(wordindex(bitstorage_size) + 1, sizeof(bitword_t));
    
    // Create a pattern with a specific offset to ensure right shift
    const counter_t source_start = WORD_SIZE_BITS - 10;  // Near the end of first word
    const counter_t pattern_size = 20;  // Crossing word boundary
    
    // Set a simple pattern
    const char* pattern = "1100110011";
    set_pattern(bitstorage, source_start, pattern_size, pattern);
    
    // Ensure we have a right shift scenario (source_bit < copy_bit)
    const bitshift_t source_bit = bitindex_calc(source_start);
    const bitshift_t copy_bit = bitindex_calc(source_start + pattern_size);
    assert(source_bit < copy_bit); // Confirm right shift condition
    
    // Extend the pattern
    continuePattern_shiftright(bitstorage, source_start, pattern_size, source_start + pattern_size * 5);
    
    // Verify the pattern was extended correctly
    bool result = verify_pattern(bitstorage, source_start + pattern_size, 
                              source_start + pattern_size * 5, pattern);
    assert(result);
    
    printf("  ✓ Right shift pattern test passed\n");
    
    // Test single-word case
    memset(bitstorage, 0, (wordindex(bitstorage_size) + 1) * sizeof(bitword_t));
    
    const counter_t single_source = 12;
    const counter_t single_size = 8;
    set_pattern(bitstorage, single_source, single_size, "10101010");
    
    // Make sure the destination is in the same word
    continuePattern_shiftright(bitstorage, single_source, single_size, single_source + single_size);
    
    result = verify_pattern(bitstorage, single_source + single_size, 
                         single_source + single_size * 2, "10101010");
    assert(result);
    
    printf("  ✓ Single-word right shift test passed\n");
    
    free(bitstorage);
}

